1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { getSettingInt } from "@/lib/settings";
4	import { AutoRefresh } from "@/components/AutoRefresh";
5	import { PortalHero } from "@/components/portal/PortalHero";
6	import { Volumes, type VolumeRow, type ServerOption } from "@/components/customer/Volumes";
7	
8	export const dynamic = "force-dynamic";
9	
10	export default async function VolumesPage() {
11	  const user = await requireUser();
12	
13	  const [volumes, servers, perGbCents] = await Promise.all([
14	    db.volume.findMany({
15	      where: { userId: user.id },
16	      include: { server: true },
17	      orderBy: { createdAt: "desc" },
18	    }),
19	    db.server.findMany({
20	      where: { userId: user.id, status: "RUNNING" },
21	      orderBy: { createdAt: "desc" },
22	    }),
23	    getSettingInt("volume_price_cents_per_gb", 10),
24	  ]);
25	
26	  const rows: VolumeRow[] = volumes.map((v) => ({
27	    id: v.id,
28	    name: v.name,
29	    sizeGB: v.sizeGB,
30	    priceCents: v.priceCents,
31	    status: v.status,
32	    serverId: v.serverId,
33	    serverName: v.server ? v.server.hostname : null,
34	  }));
35	
36	  const serverOptions: ServerOption[] = servers.map((s) => ({
37	    id: s.id,
38	    hostname: s.hostname,
39	  }));
40	
41	  const transitional = volumes.some((v) => ["PENDING", "DELETING"].includes(v.status));
42	
43	  return (
44	    <div className="space-y-6">
45	      {transitional && <AutoRefresh />}
46	      <PortalHero
47	        variant="volumes"
48	        title="Block Storage"
49	        sub="Add-on volumes you can attach to any of your running servers."
50	      />
51	      <Volumes volumes={rows} servers={serverOptions} perGbCents={perGbCents} />
52	    </div>
53	  );
54	}
