1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, assertNotImpersonating } from "./auth";
6	import { getSettingInt } from "./settings";
7	import { addMonths } from "./billing-terms";
8	import { debitWallet, InsufficientBalanceError } from "./wallet";
9	import { emailVerificationError } from "./email-verification";
10	
11	// Block storage volumes: add-on disks a customer can order, then attach to /
12	// detach from one of their running servers. A volume is billed per GB / month.
13	// The physical Proxmox disk only exists once a volume has been attached at least
14	// once; `Volume.diskName` tracks where that disk currently lives on the VM
15	// (`scsiN` while attached, `unusedN` while detached) and `Volume.serverId` the
16	// VM that physically holds it. See worker/volumes.ts for the Proxmox side.
17	
18	const MIN_GB = 1;
19	const MAX_GB = 2000;
20	
21	/**
22	 * Price (in cents) for a volume of `sizeGB`, per-GB/month from Settings.
23	 *
24	 * PRIVATE. Every export of a `"use server"` file is a public network endpoint,
25	 * and this one had a single caller — `orderVolume`, twelve lines below — yet was
26	 * reachable by anyone, signed in or not, with no auth check of any kind. Nothing
27	 * imported it; it was exported only because it happened to be written next to
28	 * the actions. That is precisely how `verifyTotpForUser` became an
29	 * unauthenticated 2FA oracle: a helper that was never meant to be an endpoint
30	 * became one by living in the wrong file with the wrong keyword in front of it.
31	 */
32	async function volumePriceCents(sizeGB: number): Promise<number> {
33	  const perGb = await getSettingInt("volume_price_cents_per_gb", 10);
34	  return Math.max(0, Math.round(sizeGB)) * perGb;
35	}
36	
37	async function ownedVolume(volumeId: string) {
38	  const user = await requireUser();
39	  const volume = await db.volume.findUnique({ where: { id: volumeId } });
40	  if (!volume) throw new Error("Not found");
41	  if (volume.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
42	  return { user, volume };
43	}
44	
45	async function ownedServer(serverId: string) {
46	  const user = await requireUser();
47	  const server = await db.server.findUnique({ where: { id: serverId } });
48	  if (!server) throw new Error("Not found");
49	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
50	  return { user, server };
51	}
52	
53	/** Reject if the server already has a job queued or running (one in-flight per server). */
54	async function serverBusy(serverId: string): Promise<boolean> {
55	  const pending = await db.job.count({
56	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
57	  });
58	  return pending > 0;
59	}
60	
61	/**
62	 * Order a new block storage volume: debit the wallet up-front (one month) and
63	 * create the Volume row PENDING plus a VOLUME_CREATE job. The job flips it to
64	 * DETACHED (available to attach). No physical disk is created until attach.
65	 */
66	export async function orderVolume(
67	  name: string,
68	  sizeGB: number
69	): Promise<{ error?: string; id?: string }> {
70	  // Spend path: this debits the wallet up front, so it takes the same guard as
71	  // every other purchase (lib/actions.ts payAndDeploy, lib/actions-disk.ts
72	  // expandServerDisk, the domain transfer actions). It was the only wallet debit
73	  // in the storage product without one.
74	  await assertNotImpersonating();
75	  const user = await requireUser();
76	  // Purchase gate: an unverified address means we cannot reach the person we
77	  // are about to charge. See lib/email-verification.ts.
78	  const unverified = await emailVerificationError(user);
79	  if (unverified) return { error: unverified };
80	
81	  const clean = (name ?? "")
82	    .replace(/[\x00-\x1f\x7f]/g, "")
83	    .replace(/\s+/g, " ")
84	    .trim();
85	  if (clean.length < 2 || clean.length > 40) {
86	    return { error: "Name must be 2–40 characters." };
87	  }
88	  const size = Math.round(Number(sizeGB));
89	  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
90	    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
91	  }
92	
93	  const priceCents = await volumePriceCents(size);
94	
95	  let volumeId: string;
96	  try {
97	    volumeId = await db.$transaction(async (tx) => {
98	      await debitWallet(tx, user.id, priceCents);
99	      await tx.walletTransaction.create({
100	        data: {
101	          userId: user.id,
102	          amountCents: -priceCents,
103	          description: `Block storage volume: ${clean} (${size} GB)`,
104	        },
105	      });
106	      const v = await tx.volume.create({
107	        data: {
108	          userId: user.id,
109	          name: clean,
110	          sizeGB: size,
111	          priceCents,
112	          status: "PENDING",
113	          expiresAt: addMonths(new Date(), 1),
114	        },
115	      });
116	      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
117	      return v.id;
118	    });
119	  } catch (e) {
120	    if (e instanceof InsufficientBalanceError) {
121	      return { error: "Insufficient balance — top up your wallet first." };
122	    }
123	    throw e;
124	  }
125	
126	  await db.auditLog.create({
127	    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
128	  });
129	  revalidatePath("/dashboard/volumes");
130	  return { id: volumeId };
131	}
132	
133	/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
134	export async function attachVolume(
135	  volumeId: string,
136	  serverId: string
137	): Promise<{ error?: string }> {
138	  const { user, volume } = await ownedVolume(volumeId);
139	  const { server } = await ownedServer(serverId);
140	
141	  if (volume.status !== "DETACHED") {
142	    return { error: "Only an available (detached) volume can be attached." };
143	  }
144	  if (!server.vmid || server.status !== "RUNNING") {
145	    return { error: "Target server must be running." };
146	  }
147	  // A volume that already holds data physically lives on one server's VM; it can
148	  // only be re-attached there (cross-node disk migration is out of scope).
149	  if (volume.serverId && volume.serverId !== serverId) {
150	    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
151	  }
152	  if (await serverBusy(serverId)) {
153	    return { error: "Another operation is already in progress on this server." };
154	  }
155	
156	  // Claim the volume with a compare-and-swap on the state we just read, then
157	  // enqueue in the SAME transaction.
158	  //
159	  // The status check above is a snapshot. Two overlapping attach requests — a
160	  // double-click, or the same volume aimed at two different servers from two
161	  // tabs — both saw DETACHED, both wrote `serverId`, and both queued a
162	  // VOLUME_ATTACH. The row ended up pointing at one server while a job tried to
163	  // hot-plug the same disk onto another, and the second attach reports success
164	  // for work that cannot happen. The CAS makes exactly one of them win.
165	  const claimed = await db.volume.updateMany({
166	    where: {
167	      id: volumeId,
168	      status: "DETACHED",
169	      // Re-assert the "lives on one VM" rule inside the swap.
170	      OR: [{ serverId: null }, { serverId }],
171	    },
172	    data: { serverId },
173	  });
174	  if (claimed.count === 0) {
175	    return { error: "This volume was just claimed by another request — refresh the page to see where it is now." };
176	  }
177	  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
178	  await db.auditLog.create({
179	    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
180	  });
181	  revalidatePath("/dashboard/volumes");
182	  revalidatePath(`/dashboard/servers/${serverId}`);
183	  return {};
184	}
185	
186	/** Detach an ATTACHED volume from its server (data is preserved as an unused disk). */
187	export async function detachVolume(volumeId: string): Promise<{ error?: string }> {
188	  const { user, volume } = await ownedVolume(volumeId);
189	  if (volume.status !== "ATTACHED" || !volume.serverId) {
190	    return { error: "Volume is not attached." };
191	  }
192	  if (await serverBusy(volume.serverId)) {
193	    return { error: "Another operation is already in progress on this server." };
194	  }
195	  await db.job.create({
196	    data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId } },
197	  });
198	  await db.auditLog.create({
199	    data: { userId: user.id, action: "volume.detach", detail: `${volumeId}` },
200	  });
201	  revalidatePath("/dashboard/volumes");
202	  revalidatePath(`/dashboard/servers/${volume.serverId}`);
203	  return {};
204	}
205	
206	/** Permanently delete a volume: detaches + destroys the disk, then removes the row. */
207	export async function deleteVolume(volumeId: string): Promise<{ error?: string }> {
208	  const { user, volume } = await ownedVolume(volumeId);
209	  if (volume.status === "DELETING") return { error: "Volume is already being deleted." };
210	
211	  // If the disk physically lives on a server, route the delete through it and
212	  // honour the one-in-flight-job guard so we don't collide with another op.
213	  if (volume.serverId) {
214	    if (await serverBusy(volume.serverId)) {
215	      return { error: "Another operation is already in progress on this server." };
216	    }
217	  }
218	  // Same compare-and-swap as attach, for the same reason and with worse stakes:
219	  // this destroys a disk. Two overlapping deletes both read a non-DELETING row
220	  // and both queued a VOLUME_DELETE for it.
221	  const claimed = await db.volume.updateMany({
222	    where: { id: volumeId, status: { not: "DELETING" } },
223	    data: { status: "DELETING" },
224	  });
225	  if (claimed.count === 0) return { error: "Volume is already being deleted." };
226	  await db.job.create({
227	    data: {
228	      type: "VOLUME_DELETE",
229	      serverId: volume.serverId ?? undefined,
230	      payload: { volumeId },
231	    },
232	  });
233	  await db.auditLog.create({
234	    data: { userId: user.id, action: "volume.delete", detail: `${volumeId}` },
235	  });
236	  revalidatePath("/dashboard/volumes");
237	  if (volume.serverId) revalidatePath(`/dashboard/servers/${volume.serverId}`);
238	  return {};
239	}
