1	import { db } from "../lib/db";
2	import { pve, node as envNode, waitForTask, nextVmid, pveFor, vmStatus } from "../lib/proxmox";
3	import { SANDBOX } from "../lib/sandbox";
4	import {
5	  withServerSsh,
6	  exec,
7	  shellQuote,
8	  QUICK_TIMEOUT_MS,
9	  SETUP_TIMEOUT_MS,
10	  INSTALL_TIMEOUT_MS,
11	} from "../lib/ssh-exec";
12	import type { Client } from "ssh2";
13	import type { Job } from "@prisma/client";
14	
15	/**
16	 * Block storage volume handlers (add-on disks attached to a VPS).
17	 *
18	 * `worker/index.ts` owns the job loop and the `handlers` map; wire these in there:
19	 *   VOLUME_CREATE: volumeCreate,
20	 *   VOLUME_ATTACH: volumeAttach,
21	 *   VOLUME_DETACH: volumeDetach,
22	 *   VOLUME_DELETE: volumeDelete,
23	 *
24	 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
25	 * so these handlers trust `payload.volumeId` / `payload.targetServerId`.
26	 *
27	 * A volume's underlying Proxmox disk only exists once it has been attached at
28	 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
29	 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
30	 * changes across detach/re-attach; we always re-scan the VM config to find the
31	 * disk's current key (scsiN while attached, unusedN while detached).
32	 *
33	 * ─── THREE THINGS THIS FILE IS RESPONSIBLE FOR ──────────────────────────────
34	 *
35	 * 1. PORTABILITY (a volume is sold as a portable disk, not a welded one).
36	 *    A Proxmox disk is OWNED by a vmid (`vm-<vmid>-disk-N`), so moving a volume
37	 *    to another server is not a DB edit — the disk has to be reassigned to the
38	 *    other VM (`move_disk` + `target-vmid`, which RENAMES the volume). See
39	 *    `reassignDiskToServer`. PVE requires both VMs on the same node, so a
40	 *    cross-node move is refused up front instead of half-done.
41	 *
42	 * 2. GUEST PREPARATION (format on first use, mount on every use).
43	 *    Nothing used to format or mount a volume: attach hot-plugged a raw disk and
44	 *    the notification told the customer to do it themselves. That is also why
45	 *    `Volume.inUse` was never knowable. `prepareGuestVolume` now does it — and is
46	 *    written to REFUSE on any ambiguity rather than risk a customer's bytes.
47	 *
48	 * 3. SAFE DETACH (never hot-unplug a live filesystem).
49	 *    A detach used to be an unconditional SCSI unplug with no sync and no
50	 *    unmount: a volume mounted at /var/lib/mysql lost its device mid-write →
51	 *    journal abort / InnoDB corruption. `releaseGuestVolume` unmounts first and
52	 *    REFUSES when the filesystem is still in use, unless the customer has given
53	 *    an explicit informed override (`payload.ackInUse`).
54	 *
55	 * ─── PROXMOX CONFIG WRITES ARE ASYNCHRONOUS ─────────────────────────────────
56	 * A config POST returns before the config file reflects it, so an immediate GET
57	 * can hand back the pre-write view. Every read-after-write in this file goes
58	 * through `waitForConfig` — that race is exactly how volumes ended up with a
59	 * null `diskName` in production.
60	 */
61	
62	async function loadVolume(job: Job) {
63	  const payload = (job.payload ?? {}) as { volumeId?: string };
64	  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
65	  const volume = await db.volume.findUnique({
66	    where: { id: payload.volumeId },
67	    // `dedicatedIp` is needed to open an SSH session to the guest (lib/sftp
68	    // connectionTarget: dedicated IP:22, else PUBLIC_IP:sshPort).
69	    include: { server: { include: { node: true, dedicatedIp: true } } },
70	  });
71	  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
72	  return volume;
73	}
74	
75	/** The server a VOLUME_ATTACH should land on. */
76	async function loadAttachTarget(job: Job, volume: Awaited<ReturnType<typeof loadVolume>>) {
77	  const payload = (job.payload ?? {}) as { targetServerId?: string };
78	  // `targetServerId` is authoritative: the enqueueing action deliberately does
79	  // NOT re-point `Volume.serverId` when a volume moves between servers, because
80	  // that pin is what stops a reinstall/restore on the server that still
81	  // physically holds the disk from purging it (worker/index.ts). Fall back to
82	  // `job.serverId` / `volume.serverId` so jobs queued by the older action (which
83	  // carried no targetServerId) still resolve correctly.
84	  const id = payload.targetServerId ?? job.serverId ?? volume.serverId;
85	  if (!id) return null;
86	  return db.server.findUnique({
87	    where: { id },
88	    include: { node: true, dedicatedIp: true },
89	  });
90	}
91	
92	/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
93	async function nodeFor(server: any) {
94	  const n =
95	    server?.node ??
96	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
97	    (await db.node.findFirst({ where: { enabled: true } }));
98	  if (!n) {
99	    return {
100	      conn: {
101	        get: pve.get,
102	        post: pve.post,
103	        put: pve.put,
104	        del: pve.del,
105	        node: envNode,
106	        waitForTask,
107	        nextVmid,
108	        vmStatus,
109	      } as any,
110	      row: null,
111	    };
112	  }
113	  return {
114	    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
115	    row: n,
116	  };
117	}
118	
119	async function notify(userId: string, title: string, body?: string, href?: string) {
120	  try {
121	    await db.notification.create({ data: { userId, title, body, href } });
122	  } catch (e) {
123	    console.error("[volumes] notify failed", e);
124	  }
125	}
126	
127	/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
128	function volidOf(configValue: unknown): string {
129	  return String(configValue ?? "").split(",")[0].trim();
130	}
131	
132	/**
133	 * True for a real Proxmox disk volid such as "vmdata:vm-102-disk-1" (or a
134	 * file/dir volid like "vmdata:102/vm-102-disk-1.raw"). Used to reject empty/
135	 * garbage read-backs so `Volume.diskName` is never persisted as a non-volid.
136	 */
137	function isRealVolid(v: unknown): v is string {
138	  return typeof v === "string" && /^[^,\s:]+:\S*vm-\d+-disk-\d+/.test(v.trim());
139	}
140	
141	/** The vmid that OWNS a volid ("vmdata:vm-102-disk-1" -> 102), or null. */
142	function vmidOfVolid(volid: unknown): number | null {
143	  const m = /vm-(\d+)-disk-\d+/.exec(String(volid ?? ""));
144	  if (!m) return null;
145	  const n = Number(m[1]);
146	  return Number.isInteger(n) && n > 0 ? n : null;
147	}
148	
149	/** All disk volids currently referenced by a VM config (scsi/virtio/ide/sata/unused). */
150	function diskVolids(config: Record<string, any>): string[] {
151	  const out: string[] = [];
152	  for (const [k, v] of Object.entries(config)) {
153	    if (typeof v !== "string") continue;
154	    if (!/^(scsi|virtio|ide|sata|unused)\d+$/.test(k)) continue;
155	    const id = volidOf(v);
156	    if (isRealVolid(id)) out.push(id);
157	  }
158	  return out;
159	}
160	
161	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
162	function freeScsiSlot(config: Record<string, any>): string {
163	  for (let i = 1; i <= 30; i++) {
164	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
165	  }
166	  throw new Error("no free scsi slot available on this VM");
167	}
168	
169	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
170	function keyForVolid(config: Record<string, any>, volid: string): string | null {
171	  for (const [k, v] of Object.entries(config)) {
172	    if (typeof v === "string" && volidOf(v) === volid) return k;
173	  }
174	  return null;
175	}
176	
177	/**
178	 * Read a VM config, polling until `ready(config)` is satisfied.
179	 *
180	 * Proxmox applies a config POST ASYNCHRONOUSLY: the call returns before the
181	 * config file is rewritten, so an immediate GET can still return the pre-write
182	 * view. Every read-after-write here uses this — the un-polled version is how
183	 * ATTACHED volumes ended up with `diskName === null`, which then made a
184	 * re-attach hand back a brand-new empty disk and orphan the real one.
185	 */
186	async function waitForConfig(
187	  conn: any,
188	  vmid: number,
189	  ready: (config: Record<string, any>) => boolean,
190	  tries = 10,
191	  delayMs = 1000
192	): Promise<Record<string, any>> {
193	  let config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
194	  for (let i = 0; i < tries && !ready(config); i++) {
195	    await new Promise((r) => setTimeout(r, delayMs));
196	    config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
197	  }
198	  return config;
199	}
200	
201	/**
202	 * Is the VM actually running right now?
203	 *
204	 * `Server.status` is NOT good enough for this decision: a row can say STOPPED or
205	 * ERROR while the VM is up (and vice versa), and getting it wrong here means
206	 * hot-unplugging a mounted filesystem. Proxmox is the ground truth; "unknown" is
207	 * reported honestly so the caller can refuse instead of assuming.
208	 */
209	async function vmRunState(conn: any, vmid: number): Promise<"running" | "stopped" | "unknown"> {
210	  try {
211	    const s = await conn.vmStatus(vmid);
212	    const st = String(s?.status ?? "");
213	    if (st === "running") return "running";
214	    if (st) return "stopped";
215	  } catch (e) {
216	    console.error(`[volumes] could not read run state of VM ${vmid}`, e);
217	  }
218	  return "unknown";
219	}
220	
221	// ===========================================================================
222	// GUEST SIDE — detect / format / mount / unmount
223	// ===========================================================================
224	/**
225	 * Everything below runs inside the customer's VM over SSH, and every command is
226	 * built the way lib/ssh-exec.ts demands: values are validated against a
227	 * shell-inert allowlist FIRST (we reject, never sanitize) and quoted second.
228	 *
229	 * The formatting decision is the most dangerous operation in this file, so it is
230	 * deliberately gated by five INDEPENDENT layers, and any one of them failing (or
231	 * being merely unclear) means we mount nothing and format nothing:
232	 *
233	 *   1. IDENTITY — the device must be one that appeared in the guest between a
234	 *      snapshot taken BEFORE the hot-plug and a poll taken after it, and exactly
235	 *      one such device may appear. We never guess "probably /dev/sdb".
236	 *   2. SIZE — that device's size must match the volume's nominal size.
237	 *   3. HISTORY — the Volume row must never have carried a filesystem
238	 *      (`fsType`/`mountPath`/`inUse` all unset). If the row says it was
239	 *      formatted but the disk looks blank, that contradiction means we may be
240	 *      looking at the wrong device: refuse and report, touch nothing.
241	 *   4. SIGNATURES — `blkid`, `wipefs -n`, children, holders and mountpoints must
242	 *      all come back empty, AND three separate 1–4 MiB windows (start, middle,
243	 *      end) must read as pure zeros. Every filesystem/partition table/LVM/LUKS/
244	 *      md-raid layout writes a header inside those windows, so "no signature and
245	 *      zeros at both ends" is as close to proof-of-blank as a disk allows.
246	 *   5. mke2fs ITSELF — `mkfs.ext4` is invoked with a SINGLE `-F`. That waives
247	 *      only the "this is a whole device, not a partition" objection; a single
248	 *      `-F` still makes mke2fs refuse a device that is mounted or otherwise in
249	 *      use by the kernel (two are required to override that), so the kernel gets
250	 *      the last veto after all our own checks.
251	 */
252	
253	const GiB = 1024 ** 3;
254	/** A bare kernel block-device name we are willing to interpolate: "sdb", "vdc". */
255	const DEV_NAME_RE = /^[a-z][a-z0-9]{1,31}$/;
256	const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
257	/** Absolute mount path we either generate or read back from the guest. */
258	const MOUNT_PATH_RE = /^\/[A-Za-z0-9._/-]{1,120}$/;
259	/** Filesystems we are willing to mount unattended. */
260	const MOUNTABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
261	/** What a blank volume gets formatted with. */
262	const VOLUME_FS = "ext4";
263	
264	/** Strip control characters and clamp — everything read back from the guest. */
265	function clean(s: unknown, max: number): string {
266	  return String(s ?? "")
267	    .replace(/[\x00-\x1f\x7f]/g, " ")
268	    .trim()
269	    .slice(0, max);
270	}
271	
272	/**
273	 * Run one guest command, turning transport failures into an empty result instead
274	 * of an exception: every caller treats "no output" as "unclear → do not touch",
275	 * so a timeout can never be mistaken for a green light (nor fail an attach that
276	 * has already been paid for and hot-plugged).
277	 */
278	async function sh(
279	  conn: Client,
280	  cmd: string,
281	  timeoutMs: number = QUICK_TIMEOUT_MS
282	): Promise<{ code: number | null; stdout: string; stderr: string }> {
283	  try {
284	    return await exec(conn, cmd, timeoutMs);
285	  } catch (e: any) {
286	    return { code: null, stdout: "", stderr: String(e?.message ?? e) };
287	  }
288	}
289	
290	/** Pull `KEY=value` out of a probe's stdout. */
291	function kv(out: string, key: string): string {
292	  return clean(new RegExp(`^${key}=(.*)$`, "m").exec(out ?? "")?.[1] ?? "", 255);
293	}
294	
295	type GuestDisk = { name: string; type: string; sizeBytes: number; fstype: string; mount: string; pkname: string };
296	
297	function parseLsblk(out: string): GuestDisk[] {
298	  const rows: GuestDisk[] = [];
299	  for (const line of (out ?? "").split("\n")) {
300	    if (!line.trim()) continue;
301	    const map: Record<string, string> = {};
302	    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) map[m[1]] = m[2];
303	    if (!map.NAME) continue;
304	    rows.push({
305	      name: clean(map.NAME, 64),
306	      type: clean(map.TYPE ?? "", 32),
307	      sizeBytes: Number(map.SIZE) || 0,
308	      fstype: clean(map.FSTYPE ?? "", 32),
309	      mount: clean(map.MOUNTPOINT ?? "", 200),
310	      pkname: clean(map.PKNAME ?? "", 64),
311	    });
312	  }
313	  return rows;
314	}
315	
316	/** Every block device the guest can see right now, or null if it could not be read. */
317	async function guestBlockDevices(conn: Client): Promise<GuestDisk[] | null> {
318	  const r = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,PKNAME 2>/dev/null`);
319	  const rows = parseLsblk(r.stdout);
320	  return rows.length ? rows : null;
321	}
322	
323	/**
324	 * Names of the whole disks that carry (or stack under) the root filesystem.
325	 * Nothing in that tree is ever a candidate, however it is stacked (partition,
326	 * LVM, dm-crypt) — walking PKNAME keeps an LVM root from ever looking "blank".
327	 */
328	async function rootDiskNames(conn: Client, rows: GuestDisk[]): Promise<Set<string>> {
329	  const byName = new Map(rows.map((r) => [r.name, r]));
330	  const topOf = (name: string): string => {
331	    let cur = name;
332	    for (let i = 0; i < 8; i++) {
333	      const row = byName.get(cur);
334	      if (!row?.pkname || row.pkname === cur) break;
335	      cur = row.pkname;
336	    }
337	    return cur;
338	  };
339	  const out = new Set<string>();
340	  const r = await sh(conn, `findmnt -nro SOURCE / 2>/dev/null | head -n1`);
341	  const src = clean(r.stdout, 128);
342	  if (src.startsWith("/dev/")) {
343	    out.add(topOf(src.slice(src.lastIndexOf("/") + 1)));
344	    const pk = await sh(conn, `lsblk -no PKNAME ${shellQuote(src)} 2>/dev/null | head -n1`);
345	    const parent = clean(pk.stdout, 64);
346	    if (parent) out.add(topOf(parent));
347	  }
348	  return out;
349	}
350	
351	/** Whole-disk names visible in the guest (excluding the root disk's tree). */
352	async function guestDiskNames(conn: Client): Promise<Set<string> | null> {
353	  const rows = await guestBlockDevices(conn);
354	  if (!rows) return null;
355	  const roots = await rootDiskNames(conn, rows);
356	  return new Set(rows.filter((d) => d.type === "disk" && !roots.has(d.name)).map((d) => d.name));
357	}
358	
359	type DeviceProbe = {
360	  ok: boolean;
361	  sizeBytes: number;
362	  fsType: string;
363	  ptType: string;
364	  uuid: string;
365	  mount: string;
366	  /** True only when EVERY blankness test came back negative. */
367	  blank: boolean;
368	  /** Human-readable list of the signs of data we found (empty when blank). */
369	  evidence: string[];
370	};
371	
372	/**
373	 * READ-ONLY interrogation of one whole disk, in a single round trip.
374	 *
375	 * `blkid -p` probes the device itself rather than the (possibly stale) cache, and
376	 * the three `dd` windows catch layouts libblkid does not know: a filesystem, a
377	 * partition table, an LVM PV label, a LUKS header, an md-raid superblock (1.0
378	 * lives at the END of the device — hence the tail window) or a swap area all put
379	 * bytes inside them. Reading is the only thing this function does.
380	 */
381	async function probeDevice(conn: Client, name: string): Promise<DeviceProbe> {
382	  const fail: DeviceProbe = { ok: false, sizeBytes: 0, fsType: "", ptType: "", uuid: "", mount: "", blank: false, evidence: ["the disk could not be interrogated"] };
383	  if (!DEV_NAME_RE.test(name)) return fail;
384	  const dev = `/dev/${name}`;
385	  const q = shellQuote(dev);
386	  const probe = [
387	    `SZ=$(blockdev --getsize64 ${q} 2>/dev/null || echo 0)`,
388	    `echo "SIZE=$SZ"`,
389	    `echo "FSTYPE=$(blkid -p -s TYPE -o value ${q} 2>/dev/null)"`,
390	    `echo "PTTYPE=$(blkid -p -s PTTYPE -o value ${q} 2>/dev/null)"`,
391	    `echo "USAGE=$(blkid -p -s USAGE -o value ${q} 2>/dev/null)"`,
392	    `echo "UUID=$(blkid -s UUID -o value ${q} 2>/dev/null)"`,
393	    `echo "MOUNT=$(findmnt -nro TARGET -S ${q} 2>/dev/null | head -n1)"`,
394	    `echo "HOLDERS=$(ls -A /sys/block/${name}/holders 2>/dev/null | tr '\\n' ' ')"`,
395	    `echo "CHILDREN=$(lsblk -no NAME ${q} 2>/dev/null | tail -n +2 | tr -d ' ' | tr '\\n' ' ')"`,
396	    `if command -v wipefs >/dev/null 2>&1; then echo "WIPEFS=$(wipefs -n ${q} 2>/dev/null | wc -l)"; else echo "WIPEFS=na"; fi`,
397	    // Three zero-windows: first 4 MiB, 1 MiB at the midpoint, last 1 MiB.
398	    `nz() { dd if=${q} bs=1048576 skip="$1" count="$2" iflag=skip_bytes,count_bytes 2>/dev/null | tr -d '\\000' | wc -c; }`,
399	    `[ "$SZ" -gt 8388608 ] 2>/dev/null && { echo "ZHEAD=$(nz 0 4194304)"; echo "ZMID=$(nz $((SZ/2)) 1048576)"; echo "ZTAIL=$(nz $((SZ-1048576)) 1048576)"; }`,
400	    `echo "PROBE=OK"`,
401	  ].join("; ");
402	
403	  const r = await sh(conn, probe, SETUP_TIMEOUT_MS);
404	  if (kv(r.stdout, "PROBE") !== "OK") return fail;
405	
406	  const sizeBytes = Number(kv(r.stdout, "SIZE")) || 0;
407	  const fsType = kv(r.stdout, "FSTYPE").toLowerCase();
408	  const ptType = kv(r.stdout, "PTTYPE").toLowerCase();
409	  const usage = kv(r.stdout, "USAGE").toLowerCase();
410	  const uuid = kv(r.stdout, "UUID");
411	  const mount = kv(r.stdout, "MOUNT");
412	  const holders = kv(r.stdout, "HOLDERS");
413	  const children = kv(r.stdout, "CHILDREN");
414	  const wipefs = kv(r.stdout, "WIPEFS");
415	  const zhead = kv(r.stdout, "ZHEAD");
416	  const zmid = kv(r.stdout, "ZMID");
417	  const ztail = kv(r.stdout, "ZTAIL");
418	
419	  const evidence: string[] = [];
420	  if (fsType) evidence.push(`a ${fsType} filesystem`);
421	  if (ptType) evidence.push(`a ${ptType} partition table`);
422	  if (usage && !fsType && !ptType) evidence.push(`a ${usage} signature`);
423	  if (uuid) evidence.push(`filesystem UUID ${uuid}`);
424	  if (mount) evidence.push(`it is mounted at ${mount}`);
425	  if (holders) evidence.push(`kernel holders (${holders})`);
426	  if (children) evidence.push(`child devices (${children})`);
427	  // `wipefs -n` prints nothing at all when it finds no magic; any line is a hit.
428	  if (wipefs !== "na" && Number(wipefs) > 0) evidence.push("on-disk signatures reported by wipefs");
429	  // A missing/short size, or zero-windows we could not read, is ambiguity — and
430	  // ambiguity is treated exactly like data.
431	  if (sizeBytes <= 8 * 1024 * 1024) evidence.push("its size could not be read");
432	  else if (zhead !== "0" || zmid !== "0" || ztail !== "0") {
433	    evidence.push(
434	      zhead === "" || zmid === "" || ztail === ""
435	        ? "the raw start/middle/end of the disk could not be read back"
436	        : "non-zero bytes at the start, middle or end of the disk"
437	    );
438	  }
439	
440	  return { ok: true, sizeBytes, fsType, ptType, uuid, mount, blank: evidence.length === 0, evidence };
441	}
442	
443	/** Does `sizeBytes` plausibly belong to a `sizeGB` volume? */
444	function sizeMatches(sizeBytes: number, sizeGB: number): boolean {
445	  const expected = Math.max(1, Math.round(sizeGB)) * GiB;
446	  // Storage back-ends round up to an extent / volblocksize, so allow a little
447	  // slack — but not enough to confuse a volume with a differently-sized disk.
448	  const slack = Math.max(64 * 1024 * 1024, expected * 0.03);
449	  return sizeBytes >= expected - slack && sizeBytes <= expected + slack;
450	}
451	
452	/** The default, stable mount point for a volume. Stable across re-attaches. */
453	function defaultMountPath(volumeId: string): string | null {
454	  const slug = String(volumeId ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
455	  if (slug.length < 8) return null;
456	  const path = `/mnt/nxeon-vol-${slug}`;
457	  return MOUNT_PATH_RE.test(path) ? path : null;
458	}
459	
460	/**
461	 * Give the guest a chance to notice a freshly hot-plugged SCSI disk, then return
462	 * the ONE device that appeared since `before`.
463	 *
464	 * Identity by set-difference (not by name, size or slot arithmetic) is what makes
465	 * the rest of this safe: the device we go on to touch is, by construction, the one
466	 * that appeared when we plugged this volume in. Zero or several new devices means
467	 * we cannot say which disk is the customer's — so we say so and stop.
468	 */
469	async function findAttachedDevice(
470	  conn: Client,
471	  before: Set<string>,
472	  sizeGB: number
473	): Promise<{ name: string } | { error: string }> {
474	  // Writing "- - -" to a SCSI host's scan node only asks the kernel to re-probe.
475	  await sh(conn, `for h in /sys/class/scsi_host/host*/scan; do echo '- - -' > "$h" 2>/dev/null; done; udevadm settle 2>/dev/null; true`);
476	
477	  let appeared: GuestDisk[] = [];
478	  for (let i = 0; i < 12; i++) {
479	    const rows = await guestBlockDevices(conn);
480	    if (rows) {
481	      const roots = await rootDiskNames(conn, rows);
482	      appeared = rows.filter((d) => d.type === "disk" && !roots.has(d.name) && !before.has(d.name));
483	      if (appeared.length) break;
484	    }
485	    await new Promise((r) => setTimeout(r, 2500));
486	  }
487	
488	  if (appeared.length === 0) {
489	    return { error: "the server did not report a new disk after the attach (a reboot usually makes it appear)" };
490	  }
491	  if (appeared.length > 1) {
492	    return { error: `${appeared.length} new disks appeared at once, so we cannot tell which one is this volume` };
493	  }
494	  const dev = appeared[0];
495	  if (!DEV_NAME_RE.test(dev.name)) {
496	    return { error: `the new disk has an unexpected device name (${dev.name.slice(0, 20)})` };
497	  }
498	  if (!sizeMatches(dev.sizeBytes, sizeGB)) {
499	    return {
500	      error:
501	        `the new disk is ${Math.round(dev.sizeBytes / GiB)} GB but this volume is ${sizeGB} GB — ` +
502	        `refusing to touch a disk we cannot positively identify`,
503	    };
504	  }
505	  return { name: dev.name };
506	}
507	
508	/**
509	 * Persist an ALREADY-FORMATTED filesystem: an /etc/fstab entry BY UUID (never by
510	 * /dev/sdX — a volume can come back as a different letter, and then fstab mounts
511	 * the wrong disk) with `nofail`, then mount it.
512	 *
513	 * `nofail` is not optional. A volume can be detached, moved to another server or
514	 * simply fail to appear; without `nofail` systemd holds local-fs.target and the
515	 * customer's server does not finish booting. An unmounted disk is a support
516	 * ticket, a server that will not boot is an outage.
517	 *
518	 * Idempotent: the grep guard and the `mountpoint -q` short-circuit make a re-run
519	 * a no-op. NEVER formats — that decision belongs to the caller alone.
520	 */
521	async function mountVolumeFs(
522	  conn: Client,
523	  devName: string,
524	  mountPath: string,
525	  fsType: string
526	): Promise<{ ok: true; uuid: string } | { ok: false; error: string }> {
527	  if (!DEV_NAME_RE.test(devName)) return { ok: false, error: "device name failed validation" };
528	  if (!MOUNT_PATH_RE.test(mountPath) || mountPath.includes("..") || mountPath.includes("//")) {
529	    return { ok: false, error: `unsupported mount path ${mountPath.slice(0, 40)}` };
530	  }
531	  if (!MOUNTABLE_FS.has(fsType)) return { ok: false, error: `unsupported filesystem ${fsType.slice(0, 20)}` };
532	
533	  const dev = shellQuote(`/dev/${devName}`);
534	  const path = shellQuote(mountPath);
535	
536	  // udev may still be settling right after a mkfs; give the UUID two chances.
537	  let uuid = "";
538	  for (let i = 0; i < 2 && !UUID_RE.test(uuid); i++) {
539	    if (i) await sh(conn, `udevadm settle 2>/dev/null; true`);
540	    uuid = clean((await sh(conn, `blkid -s UUID -o value ${dev} 2>/dev/null`)).stdout, 64);
541	  }
542	  if (!UUID_RE.test(uuid)) return { ok: false, error: "could not read a filesystem UUID back" };
543	
544	  // Refuse to stack our mount on top of somebody else's filesystem.
545	  const occupied = await sh(conn, `findmnt -nro SOURCE --mountpoint ${path} 2>/dev/null | head -n1`);
546	  const occupiedBy = clean(occupied.stdout, 128);
547	  if (occupiedBy && occupiedBy !== `/dev/${devName}`) {
548	    return { ok: false, error: `${mountPath} is already in use by ${occupiedBy}` };
549	  }
550	
551	  await sh(conn, `mkdir -p ${path}`);
552	  await sh(
553	    conn,
554	    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${uuid}' ${path} ${shellQuote(fsType)} >> /etc/fstab`
555	  );
556	  await sh(conn, `mountpoint -q ${path} || mount ${path} 2>&1 || mount ${dev} ${path} 2>&1`, SETUP_TIMEOUT_MS);
557	  const live = await sh(conn, `mountpoint -q ${path} && echo MOUNTED`);
558	  if (!clean(live.stdout, 32).includes("MOUNTED")) {
559	    return { ok: false, error: `mounting ${mountPath} failed` };
560	  }
561	  return { ok: true, uuid };
562	}
563	
564	/** Where should this volume be mounted? Never invents a path over an existing layout. */
565	async function resolveMountPath(
566	  conn: Client,
567	  volume: { id: string; mountPath: string | null },
568	  uuid: string
569	): Promise<string | null> {
570	  // 1) An fstab entry for THIS filesystem wins: it is where the guest already
571	  //    expects the disk, and the migration engine bind-mounts Docker's stores out
572	  //    of that directory. Mounting somewhere else would leave those binds dangling.
573	  if (UUID_RE.test(uuid)) {
574	    const r = await sh(conn, `awk -v u="UUID=${uuid}" '$1==u {print $2; exit}' /etc/fstab 2>/dev/null`);
575	    const fromFstab = clean(r.stdout, 200);
576	    if (MOUNT_PATH_RE.test(fromFstab)) return fromFstab;
577	  }
578	  // 2) Then the path we recorded last time (kept across a detach for the same reason).
579	  if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) return volume.mountPath;
580	  // 3) Otherwise our own stable path.
581	  return defaultMountPath(volume.id);
582	}
583	
584	type PrepareResult =
585	  | { prepared: true; fsType: string; mountPath: string; detail: string }
586	  | { prepared: false; detail: string; fsType?: string };
587	
588	/**
589	 * Make an attached volume usable: format it if (and ONLY if) it is provably
590	 * blank, mount it either way, and record enough to make a later detach safe.
591	 *
592	 * `formatAllowed` is the DB-side half of the format gate: the Volume row must
593	 * never have carried a filesystem. It is deliberately separate from the
594	 * disk-side evidence so that the two have to agree.
595	 */
596	async function prepareGuestVolume(
597	  server: any,
598	  volume: { id: string; sizeGB: number; mountPath: string | null; fsType: string | null; inUse: boolean },
599	  before: Set<string>
600	): Promise<PrepareResult> {
601	  const formatAllowed = !volume.fsType && !volume.mountPath && !volume.inUse;
602	  try {
603	    return await withServerSsh(server, async (conn) => {
604	      const found = await findAttachedDevice(conn, before, volume.sizeGB);
605	      if ("error" in found) return { prepared: false, detail: found.error };
606	
607	      const probe = await probeDevice(conn, found.name);
608	      if (!probe.ok) {
609	        return { prepared: false, detail: `/dev/${found.name} could not be interrogated, so it was left untouched` };
610	      }
611	
612	      // ── Already mounted: adopt it, change nothing about the data. ──────────
613	      if (probe.mount) {
614	        const fsType = probe.fsType || "unknown";
615	        if (!MOUNT_PATH_RE.test(probe.mount)) {
616	          return { prepared: false, detail: `it is already mounted at an unsupported path (${probe.mount.slice(0, 40)})`, fsType: probe.fsType || undefined };
617	        }
618	        // Make sure that mount survives a reboot, without touching the contents.
619	        if (MOUNTABLE_FS.has(fsType) && UUID_RE.test(probe.uuid)) {
620	          await sh(
621	            conn,
622	            `grep -q "UUID=${probe.uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${probe.uuid}' ${shellQuote(probe.mount)} ${shellQuote(fsType)} >> /etc/fstab`
623	          );
624	        }
625	        return {
626	          prepared: true,
627	          fsType,
628	          mountPath: probe.mount,
629	          detail: `already mounted at ${probe.mount} (${fsType}) — its contents were not touched`,
630	        };
631	      }
632	
633	      // ── Carries data: mount a filesystem we understand, never reformat. ────
634	      if (probe.fsType || probe.ptType) {
635	        if (probe.ptType || !MOUNTABLE_FS.has(probe.fsType)) {
636	          // A partition table (or an fs we do not mount unattended) means the
637	          // layout is the customer's business; guessing which partition to mount
638	          // is how you mount the wrong thing.
639	          return {
640	            prepared: false,
641	            fsType: probe.fsType || probe.ptType,
642	            detail:
643	              `/dev/${found.name} already contains ${probe.evidence[0] ?? "existing data"}. ` +
644	              `It was attached but NOT formatted or mounted — mount it yourself so nothing is guessed.`,
645	          };
646	        }
647	        const path = await resolveMountPath(conn, volume, probe.uuid);
648	        if (!path) return { prepared: false, fsType: probe.fsType, detail: "could not derive a mount point" };
649	        const m = await mountVolumeFs(conn, found.name, path, probe.fsType);
650	        if (!m.ok) return { prepared: false, fsType: probe.fsType, detail: m.error };
651	        return {
652	          prepared: true,
653	          fsType: probe.fsType,
654	          mountPath: path,
655	          detail: `existing ${probe.fsType} filesystem mounted at ${path} — nothing was reformatted`,
656	        };
657	      }
658	
659	      // ── Nothing detected on the disk. Format ONLY if history agrees. ───────
660	      if (!formatAllowed) {
661	        // The row says this volume carries a filesystem but the disk shows no
662	        // trace of one. That is a contradiction, and the likeliest explanations
663	        // (wrong device, a disk that was recreated empty) both end with somebody
664	        // formatting data. Stop and hand it to a human.
665	        return {
666	          prepared: false,
667	          detail:
668	            `refusing to touch /dev/${found.name}: this volume is recorded as ${volume.fsType ?? "formatted"}` +
669	            `${volume.mountPath ? ` mounted at ${volume.mountPath}` : ""}, but the disk reports no filesystem at all. ` +
670	            `Nothing was formatted or mounted — please contact support before writing to it.`,
671	        };
672	      }
673	      if (!probe.blank) {
674	        return {
675	          prepared: false,
676	          detail: `refusing to format /dev/${found.name}: ${probe.evidence.join("; ")}`,
677	        };
678	      }
679	
680	      // Single `-F`: waives only the "whole device, not a partition" objection.
681	      // mke2fs still refuses a device it believes is mounted or in use, which is
682	      // the last independent veto after our own five checks.
683	      const mk = await sh(
684	        conn,
685	        `mkfs.${VOLUME_FS} -F -m 0 -L nxeon-vol ${shellQuote(`/dev/${found.name}`)} 2>&1`,
686	        INSTALL_TIMEOUT_MS
687	      );
688	      if (mk.code !== 0) {
689	        return { prepared: false, detail: `mkfs.${VOLUME_FS} refused /dev/${found.name}: ${clean(mk.stdout || mk.stderr, 200)}` };
690	      }
691	      const path = (await resolveMountPath(conn, volume, "")) ?? defaultMountPath(volume.id);
692	      if (!path) return { prepared: false, detail: "could not derive a mount point" };
693	      const m = await mountVolumeFs(conn, found.name, path, VOLUME_FS);
694	      if (!m.ok) return { prepared: false, fsType: VOLUME_FS, detail: m.error };
695	      return {
696	        prepared: true,
697	        fsType: VOLUME_FS,
698	        mountPath: path,
699	        detail: `formatted ${VOLUME_FS} and mounted at ${path} (fstab UUID entry with nofail)`,
700	      };
701	    });
702	  } catch (e: any) {
703	    return { prepared: false, detail: `the server could not be reached to prepare the disk (${clean(e?.message ?? e, 120)})` };
704	  }
705	}
