707	/** What the customer can run by hand when we deliberately did not prepare the disk. */
708	function manualPrepareHint(volumeId: string): string {
709	  const path = defaultMountPath(volumeId) ?? "/mnt/data";
710	  return (
711	    `lsblk   # find the new disk, e.g. /dev/sdb\n` +
712	    `mkfs.ext4 /dev/sdb && mkdir -p ${path} && mount /dev/sdb ${path}\n` +
713	    `echo "UUID=$(blkid -s UUID -o value /dev/sdb) ${path} ext4 defaults,nofail 0 2" >> /etc/fstab`
714	  );
715	}
716	
717	type ReleaseResult =
718	  /** The filesystem is not (or no longer) mounted — the disk can be unplugged. */
719	  | { released: true; detail: string }
720	  /** Something still depends on it. Refuse unless the customer overrode it. */
721	  | { released: false; dependents: string[]; detail: string };
722	
723	/**
724	 * Take the volume's filesystem out of service BEFORE the disk is unplugged.
725	 *
726	 * The old detach was a bare SCSI unplug: no sync, no unmount, no guest-agent
727	 * involvement. A volume mounted at /var/lib/mysql simply lost its device mid
728	 * write — journal abort, InnoDB corruption — while the UI promised "Data is
729	 * preserved.". And the same primitive fires with no human present from billing
730	 * (worker/product-renewals.ts queues VOLUME_DETACH on an overdue volume attached
731	 * to a RUNNING VM), which is why the refusal lives here and not only in the UI.
732	 *
733	 * Nothing is mutated before the decision: `sync` and the probes are harmless, the
734	 * fstab edit happens only once we know the unmount is going ahead. If the worker
735	 * dies between the unmount and the fstab edit the entry is stale — which is
736	 * survivable only because every entry we write carries `nofail`.
737	 */
738	async function releaseGuestVolume(
739	  server: any,
740	  volume: { id: string; sizeGB: number; mountPath: string | null; fsType: string | null; inUse: boolean },
741	  ackInUse: boolean
742	): Promise<ReleaseResult> {
743	  const knownFs = !!(volume.inUse || volume.mountPath || volume.fsType);
744	  try {
745	    return await withServerSsh(server, async (conn) => {
746	      // Which device is ours? The recorded mount point is the reliable link (it
747	      // is unique to this volume); otherwise fall back to a size match, and treat
748	      // "several disks could be it" as in-use rather than guessing.
749	      let devName = "";
750	      let mountPath = "";
751	      if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) {
752	        const r = await sh(conn, `findmnt -nro SOURCE --mountpoint ${shellQuote(volume.mountPath)} 2>/dev/null | head -n1`);
753	        const src = clean(r.stdout, 128);
754	        if (src.startsWith("/dev/")) {
755	          devName = src.slice(5);
756	          mountPath = volume.mountPath;
757	        }
758	      }
759	      if (!devName) {
760	        const rows = await guestBlockDevices(conn);
761	        if (!rows) {
762	          return knownFs
763	            ? { released: false, dependents: [], detail: "the server's disks could not be listed, so we cannot confirm the filesystem is idle" }
764	            : { released: true, detail: "no filesystem is recorded for this volume and the guest could not be probed" };
765	        }
766	        const roots = await rootDiskNames(conn, rows);
767	        const candidates = rows.filter(
768	          (d) => d.type === "disk" && !roots.has(d.name) && sizeMatches(d.sizeBytes, volume.sizeGB)
769	        );
770	        const mounted = candidates.filter((d) => d.mount || rows.some((o) => o.pkname === d.name && o.mount));
771	        if (mounted.length === 0) {
772	          return { released: true, detail: "the volume's filesystem is not mounted" };
773	        }
774	        if (mounted.length > 1) {
775	          return {
776	            released: false,
777	            dependents: mounted.map((d) => `/dev/${d.name} mounted at ${d.mount || "a partition mount point"}`),
778	            detail: `${mounted.length} mounted disks match this volume's size, so we cannot tell which one to unmount`,
779	          };
780	        }
781	        devName = mounted[0].name;
782	        mountPath = mounted[0].mount;
783	      }
784	      if (!DEV_NAME_RE.test(devName) || !MOUNT_PATH_RE.test(mountPath)) {
785	        return { released: true, detail: "the volume's filesystem is not mounted" };
786	      }
787	
788	      const path = shellQuote(mountPath);
789	      const uuid = clean((await sh(conn, `blkid -s UUID -o value ${shellQuote(`/dev/${devName}`)} 2>/dev/null`)).stdout, 64);
790	
791	      // Flush before anything else — cheap, and the one thing the old code never did.
792	      await sh(conn, `sync`, SETUP_TIMEOUT_MS);
793	
794	      const plain = await sh(conn, `umount ${path} 2>&1`, SETUP_TIMEOUT_MS);
795	      const stillMounted = clean((await sh(conn, `mountpoint -q ${path} && echo BUSY`)).stdout, 32).includes("BUSY");
796	
797	      if (stillMounted) {
798	        const dependents = await mountDependents(conn, mountPath);
799	        if (!ackInUse) {
800	          return {
801	            released: false,
802	            dependents,
803	            detail: `${mountPath} could not be unmounted: ${clean(plain.stdout || plain.stderr, 160) || "the filesystem is in use"}`,
804	          };
805	        }
806	        // Informed override: the customer accepted that whatever is using this
807	        // filesystem will break. A lazy unmount detaches the tree now and lets
808	        // the kernel release it when the last reference goes, which is still far
809	        // better than yanking the device out from under an open file.
810	        await removeFstabEntry(conn, uuid);
811	        await sh(conn, `umount -l ${path} 2>&1`, SETUP_TIMEOUT_MS);
812	        await sh(conn, `sync`, SETUP_TIMEOUT_MS);
813	        return {
814	          released: true,
815	          detail: `${mountPath} was still in use (${dependents.join(", ") || "unknown holders"}) and was force-unmounted on your instruction`,
816	        };
817	      }
818	
819	      await removeFstabEntry(conn, uuid);
820	      return { released: true, detail: `${mountPath} was unmounted cleanly` };
821	    });
822	  } catch (e: any) {
823	    // Cannot reach the guest. If we know it carries a mounted filesystem we
824	    // refuse: an unverified hot-unplug is exactly the corruption we are here to
825	    // prevent. If no filesystem was ever recorded there is nothing to corrupt.
826	    const why = clean(e?.message ?? e, 120);
827	    return knownFs
828	      ? { released: false, dependents: [], detail: `the server could not be reached to unmount the volume first (${why})` }
829	      : { released: true, detail: `no filesystem is recorded for this volume and the server is unreachable (${why})` };
830	  }
831	}
