844	/** Name what is holding a mount point open, for an honest refusal message. */
845	async function mountDependents(conn: Client, mountPath: string): Promise<string[]> {
846	  if (!MOUNT_PATH_RE.test(mountPath)) return [];
847	  const q = shellQuote(mountPath);
848	  const r = await sh(
849	    conn,
850	    // Bind mounts sourced from inside this filesystem (how Docker's stores are
851	    // relocated onto a volume), then the processes with files open under it.
852	    `findmnt -rno TARGET,SOURCE 2>/dev/null | awk -v p=${q} '{ if (index($2, p"/")==1 || index($1, p"/")==1) print "bind " $1 }' | sort -u | head -n 8; ` +
853	      `P=$(fuser -Mm ${q} 2>/dev/null | tr -cd '0-9 \\n'); ` +
854	      `[ -n "$P" ] && ps -o comm= -p $P 2>/dev/null | sort -u | head -n 8 | sed 's/^/proc /'; true`
855	  );
856	  const out: string[] = [];
857	  for (const line of clean(r.stdout, 2000).split("\n")) {
858	    const t = line.trim();
859	    if (t.startsWith("bind ")) out.push(`${t.slice(5)} (bind-mounted out of this volume)`);
860	    else if (t.startsWith("proc ")) out.push(`${t.slice(5)} (running process)`);
861	  }
862	  return out.slice(0, 10);
863	}
